package com.sentinelcore.assetservice.service; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.sentinelcore.assetservice.dto.*; import com.sentinelcore.assetservice.entity.*; import com.sentinelcore.assetservice.repository.SecurityReviewRepository;
@Service public class SecurityReviewService { private final SecurityReviewRepository repository; private final AssetService assetService; private final AuditService auditService; public SecurityReviewService(SecurityReviewRepository r,AssetService a,AuditService audit){repository=r;assetService=a;auditService=audit;} @Transactional public SecurityReviewResponse create(SecurityReviewRequest request){User user=assetService.getCurrentUser(); SecurityReview review=new SecurityReview(); review.setReviewer(user); apply(review,request); SecurityReview saved=repository.save(review); auditService.record(user,"SECURITY_REVIEW_CREATED","SECURITY_REVIEW",saved.getId(),"SUCCESS","HIGH","Security review created",null,saved.getStatus().name()); return response(saved);} @Transactional(readOnly=true) public List<SecurityReviewResponse> all(){return repository.findAllByOrderByReviewDateDesc().stream().map(this::response).toList();} @Transactional public SecurityReviewResponse update(UUID id,SecurityReviewRequest request){SecurityReview review=repository.findById(id).orElseThrow(); apply(review,request); SecurityReview saved=repository.save(review); auditService.record(assetService.getCurrentUser(),"SECURITY_REVIEW_UPDATED","SECURITY_REVIEW",id,"SUCCESS","HIGH","Security review updated",null,saved.getStatus().name()); return response(saved);} private void apply(SecurityReview r,SecurityReviewRequest q){r.setScope(q.getScope());r.setReviewPeriod(q.getReviewPeriod());r.setFindings(q.getFindings());r.setAnomalies(q.getAnomalies());r.setComments(q.getComments());if(q.getStatus()!=null)r.setStatus(q.getStatus());} private SecurityReviewResponse response(SecurityReview r){return new SecurityReviewResponse(r.getId(),r.getReviewer().getEmail(),r.getScope(),r.getReviewPeriod(),r.getFindings(),r.getAnomalies(),r.getStatus(),r.getComments(),r.getReviewDate());} }